  step("migraine", "Migraine attack", "At onset", ["Paracetamol 650 mg or indomethacin 50 mg, with prochlorperazine 10 mg for nausea (ICMR STW).", "If simple analgesia fails: oral triptan combined with a non-steroidal anti-inflammatory drug (NSAID) or paracetamol (NICE 1.3.10).", "Do not offer ergots or opioids (NICE 1.3.14)."]),
  step("prevent", "Migraine prevention", "More than 2 attacks a month", ["Propranolol or flunarizine for a 2-month trial (ICMR STW); NICE offers topiramate or propranolol, or amitriptyline (NICE 1.3.17–1.3.18).", "Review need 6 months after starting (NICE 1.3.22); taper after remission (ICMR STW).", "Sleep at least 6 hours, regular meals, avoid triggers (ICMR STW)."]),
  step("tth", "Tension-type headache", "Episodes", ["Acute: aspirin, paracetamol or an NSAID; no opioids (NICE 1.3.7–1.3.8).", "Chronic tension-type: indomethacin for 7 days, amitriptyline at bedtime (ICMR STW)."]),
  step("cluster", "Cluster headache", "During attack", ["100% oxygen at 12 L/min or more by non-rebreathing mask, and/or subcutaneous triptan (NICE 1.3.29–1.3.30).", "Do not give paracetamol, NSAIDs, opioids, ergots or oral triptans (NICE 1.3.32).", "Refer to a tertiary centre (ICMR STW); verapamil prevention under specialist advice (NICE 1.3.33)."]),
