  rx("Chronic tension-type headache", "Short course analgesic", "Chronic tension-type headache", "Adults", "Indomethacin", "25 mg", "Oral", "Three times daily", "7 days", ADULT, NOT_ABX, "Avoid in significant kidney impairment (NSAID).", NS, ["Gastrointestinal symptoms"], ["Peptic ulcer, kidney impairment"], "ha", HA),
  rx("Chronic tension-type headache", "Preventive medicine", "Chronic tension-type headache", "Adults", "Amitriptyline", "10 mg", "Oral", "At bedtime", "Adequate duration, then taper after remission (ICMR STW)", ADULT, NOT_ABX, NS, NS, ["Sedation, dry mouth", "Electrocardiogram (ECG) if cardiac disease"], ["Recent myocardial infarction, arrhythmia, glaucoma"], "ha", HA),
  rx("Cluster headache — acute attack", "Oxygen", "Cluster headache attack", "Adults", "Oxygen (100%)", "100% oxygen at 12 L/min or more", "Non-rebreathing mask with reservoir bag", "At attack onset", "Until attack ends", "Specialist advice in children.", NOT_ABX, "No change.", "No change.", ["Response within 15 minutes"], ["Caution in chronic obstructive pulmonary disease (COPD) with hypercapnia"], "cg150", "Recommendations 1.3.29–1.3.30"),
